    end
  end
  on_linux do
    on_arm do
      url "https://downloads.nubisco.io/alter/v0.1.25/alter-0.1.25-linux-arm64.tar.gz"
      sha256 "4a646176087390df53891c9daa7ff8e31bab77536dc72a8727e15ac805b65f51"
