      sha256 "09ec6316472b8457720b0ac848a7aa6fb718d162dba81b173a1f9047996a77b5"
    end
  end

  def install
    prefix.install "bin", "share"
  end

  # `brew services start alter` keeps it running, as `alter service install` does.
  service do
